def repl(s):
    for a,b in TA_REPL: s=s.replace(a,b)
    return s

def strip_prefix(s):
    for p in ("Understanding the topic","Deeper understanding","கருத்தை விரிவாகப் புரிந்துகொள்ளுதல்","ஆழமான புரிதல்","காட்சி வழிக் கற்றல்"):
        if s.startswith(p):
            s=s[len(p):].lstrip(" :—–-")
    return s

def clean_block(b,lang):
    if lang=="tamil":
        for k in ("title","text","caption"):
            if isinstance(b.get(k),str): b[k]=repl(b[k])
        if b.get("rows"):
            b["rows"]=[[repl(str(x)) for x in row] for row in b["rows"]]
    title=(b.get("title") or "").strip()
    text=(b.get("text") or "").strip()
    if title and text.startswith(title):
        text=text[len(title):].lstrip(" :—–-")
    b["text"]=strip_prefix(text)
    if lang=="english" and b.get("kind")=="think_apply":
        b["text"]=re.sub(r"\s*Self-check:.*$","",b["text"],flags=re.S).strip()

