for u in book["units"]:
    if u["number"]==2: u["titleTa"]="சூழ்நிலை மண்டலங்களும் இயற்கை வளங்களும்"
    if u["number"]==3: u["titleTa"]="உயிரிய பல்வகைத்தன்மையும் பாதுகாப்பும்"
    u["titleTa"]=repl(u["titleTa"])
    for l in u["lessons"]:
        l["titleTa"]=TITLE_TA.get(l["number"],repl(l["titleTa"]))
        hasfig=any(b.get("kind") in ("figure","svg_figure") and b.get("figure") for b in l["tamil"])
        for lang in ("english","tamil"):
            out=[]
            for b in l[lang]:
                kind=b.get("kind")
                txt=(b.get("text") or "").strip()
                title=(b.get("title") or "").strip()
                if kind in ("learning_outcome","level"): continue
                if lang=="english" and kind=="visual_or_feature" and txt.startswith("Foundation Define the concept"): continue
                if lang=="english" and kind=="div": continue
                if lang=="tamil" and title=="தமிழில் விளக்கம்" and txt in ("","தமிழில் விளக்கம்"): continue
                if lang=="tamil" and hasfig and kind in ("visual_or_feature","supplemental") and title=="தமிழில் விளக்கம்" and txt.startswith("தமிழில் விளக்கம் காட்சி வழிக் கற்றல்"): continue
                clean_block(b,lang)
                if lang=="tamil" and (b.get("title") or "")=="தமிழில் விளக்கம்": b["title"]=CONCEPT[l["number"]]
                out.append(b)
            l[lang]=out

def lesson(n):
    return next(l for u in book["units"] for l in u["lessons"] if l["number"]==n)
def block(l,lang,kind):
    return next(b for b in l[lang] if b.get("kind")==kind)

